  const antiRaidResponse=(settings:AntiRaidSettings)=>({settings,active:settings.enabled&&!!settings.activeUntil&&settings.activeUntil.getTime()>Date.now()});
  app.get("/api/guild/:guildId/anti-raid",requireGuildAdmin,async(req,res)=>{
    try{const guild=client.guilds.cache.get(String(req.params.guildId));if(!guild)return res.status(404).json({error:"Server not found."});
      const [settings]=await AntiRaidSettings.findOrCreate({where:{guildId:guild.id}});
      const channels=await guild.channels.fetch();
      res.json({...antiRaidResponse(settings),channels:[...channels.values()].filter(ch=>ch&&(ch.type===ChannelType.GuildText||ch.type===ChannelType.GuildAnnouncement)).map(ch=>({id:ch!.id,name:ch!.name}))});
    }catch{res.status(500).json({error:"Failed to load anti-raid configuration."})}
  });
  app.put("/api/guild/:guildId/anti-raid",requireGuildAdmin,async(req,res)=>{
    try{const guild=client.guilds.cache.get(String(req.params.guildId));if(!guild)return res.status(404).json({error:"Server not found."});
      const body=req.body??{};
      if(typeof body.enabled!=="boolean")return res.status(400).json({error:"Enabled must be a boolean."});
      for(const [key,min,max] of [["joinThreshold",3,100],["windowSeconds",5,300],["lockdownMinutes",1,1440]] as const){
        if(!Number.isInteger(body[key])||body[key]<min||body[key]>max)return res.status(400).json({error:key+" must be an integer between "+min+" and "+max+"."});
      }
      if(!["kick","ban","none"].includes(body.action))return res.status(400).json({error:"Select kick, ban, or alert only."});
      const channelId=body.alertChannelId;
      if(channelId!==null&&channelId!==""){
        if(typeof channelId!=="string"||!/^\d+$/.test(channelId))return res.status(400).json({error:"Select a valid alert channel."});
        const channel=await guild.channels.fetch(channelId).catch(()=>null);
        if(!channel||(channel.type!==ChannelType.GuildText&&channel.type!==ChannelType.GuildAnnouncement))return res.status(400).json({error:"Select a text or announcement channel in this server."});
      }
      const [settings]=await AntiRaidSettings.findOrCreate({where:{guildId:guild.id}});
      settings.enabled=body.enabled;settings.joinThreshold=body.joinThreshold;settings.windowSeconds=body.windowSeconds;settings.action=body.action;settings.alertChannelId=channelId||null;settings.lockdownMinutes=body.lockdownMinutes;
      if(!settings.enabled)await stopAntiRaid(settings,true);else await settings.save();
      res.json({ok:true,...antiRaidResponse(settings)});
    }catch{res.status(500).json({error:"Failed to save anti-raid configuration."})}
  });
